"""Assemble native monochrome frames generated by the firmware's desktop tests."""

from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

root = Path(__file__).resolve().parents[1]
screens = root / ".local/screens"
tiles = [
    ("lock", "锁屏"),
    ("home", "首页"),
    ("reader", "读书"),
    ("menu", "阅读菜单"),
    ("tools", "快捷设置"),
    ("wifi", "输入 Wi-Fi 密码"),
    ("learning", "英语练习"),
    ("feedback", "答题反馈"),
    ("lan", "局域网文件服务"),
]
canvas = Image.new("RGB", (792, 1410), "#eeeee9")
draw = ImageDraw.Draw(canvas)
font = ImageFont.truetype(str(root / "assets/fonts/霞鹜臻楷.ttf"), 18)
for index, (file, label) in enumerate(tiles):
    x, y = 20 + (index % 3) * 256, 12 + (index // 3) * 466
    frame = Image.open(screens / (file + ".pbm"))
    if frame.mode != "1" or frame.size != (240, 416):
        raise ValueError(file)
    draw.text((x, y), label, font=font, fill="#24372d")
    draw.rectangle((x - 1, y + 29, x + 240, y + 446), outline="#77796d")
    canvas.paste(frame.convert("RGB"), (x, y + 30))
(root / "artifacts").mkdir(exist_ok=True)
canvas.save(root / "artifacts/固件实绘.png")
